import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Function} textureLoader.loadTexture
 * @property {Object} emit
 */

/**
 * Creates a textured billboard plane.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: CtxGroup, Mesh: CtxMesh, PlaneGeometry: CtxPlaneGeometry, MeshBasicNodeMaterial: CtxMeshBasicNodeMaterial } = ctx.THREE;

  // Root container (position/rotation/scale are applied by the adapter)
  const root = new CtxGroup();

  // Determine aspect ratio from the atlas region (512 x 320)
  const REGION_W = 512;
  const REGION_H = 320;
  const aspect = REGION_W / REGION_H; // 1.6

  const geometry = new CtxPlaneGeometry(aspect, 1);
  const material = new CtxMeshBasicNodeMaterial();

  // Initial material without texture; will be populated once texture loads
  material.colorNode = null; // ensure node material is used

  const mesh = new CtxMesh(geometry, material);
  root.add(mesh);

  // Placeholder for the loaded texture so we can dispose it later
  let loadedTexture = null;

  // Load texture asynchronously; material will be updated when ready
  if (config && typeof config.imageUrl === 'string') {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;

      // Apply UV offset/scale for the atlas region.
      // If the texture has image dimensions, compute normalized coordinates.
      const img = tex.image;
      if (img && img.width && img.height) {
        tex.offset.set(
          0 / img.width,
          0 / img.height
        );
        tex.repeat.set(
          REGION_W / img.width,
          REGION_H / img.height
        );
      }

      // Assign the texture to the node material
      material.mapNode = texture(tex);
      material.needsUpdate = true;
    });
  }

  // No interaction primitives; expose empty handler map for consistency
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry
    if (geometry) geometry.dispose();

    // Dispose material
    if (material) material.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) loadedTexture.dispose();

    // Kill any GSAP timelines (none in this node but defensive)
    gsap.globalTimeline.clear(); // clears all timelines that might be attached globally
  };

  return root;
}
